<?php namespace App\Models;
final class Attendance extends BaseModel { public function record(int $session,int $student,string $status='present'):void{$this->db->prepare('INSERT INTO attendance(session_id,student_id,status) VALUES(?,?,?)')->execute([$session,$student,$status]);} public function history(int $uid):array{return $this->all('SELECT sub.code,sub.name,x.title,a.status,a.recorded_at FROM attendance a JOIN students s ON s.id=a.student_id JOIN attendance_sessions x ON x.id=a.session_id JOIN subjects sub ON sub.id=x.subject_id WHERE s.user_id=? ORDER BY a.recorded_at DESC',[$uid]);} public function live(int $session):array{return $this->all('SELECT u.full_name,s.student_no,a.status,a.recorded_at FROM attendance a JOIN students s ON s.id=a.student_id JOIN users u ON u.id=s.user_id WHERE a.session_id=? ORDER BY a.recorded_at DESC',[$session]);} }